def transform(grid):
    """Keep and complete the dense rectangular color regions; discard scattered noise."""
    h, w = len(grid), len(grid[0])
    if any(len(row) != w for row in grid):
        raise ValueError("grid must be rectangular")
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]
    out = [[bg] * w for _ in range(h)]

    for color in {v for row in grid for v in row if v != bg}:
        cells = [(r, c) for r in range(h) for c in range(w) if grid[r][c] == color]
        rows = sorted({r for r, _ in cells})
        cols = sorted({c for _, c in cells})
        candidates = []
        # Search bounding boxes supported by actual pixels of this color. Dense
        # boxes may have holes or foreign-color speckles that should be repaired.
        for r0, r1 in combinations(rows, 2):
            for c0, c1 in combinations(cols, 2):
                area = (r1 - r0 + 1) * (c1 - c0 + 1)
                count = sum(r0 <= r <= r1 and c0 <= c <= c1 for r, c in cells)
                if area >= 4 and count >= 4 and count / area >= 0.70:
                    if all(any(r == rr for r, _ in cells) for rr in range(r0, r1 + 1)) and all(any(c == cc for _, c in cells) for cc in range(c0, c1 + 1)):
                        candidates.append((r0, r1, c0, c1))
        # Long straight bars are also legitimate rectangular objects (one demo
        # contains a damaged 1x7 bar); isolated short marks remain noise.
        for r in rows:
            line = [c for rr, c in cells if rr == r]
            if len(line) >= 4 and max(line) - min(line) + 1 <= len(line) / 0.70:
                candidates.append((r, r, min(line), max(line)))
        for c in cols:
            line = [r for r, cc in cells if cc == c]
            if len(line) >= 4 and max(line) - min(line) + 1 <= len(line) / 0.70:
                candidates.append((min(line), max(line), c, c))

        # Discard candidate boxes strictly contained in another supported box;
        # the outer box represents a single intact or repaired region.
        candidates = sorted(set(candidates), key=lambda b: ((b[1]-b[0]+1)*(b[3]-b[2]+1), b))
        maximal = []
        for box in candidates:
            r0, r1, c0, c1 = box
            if not any(a <= r0 and b >= r1 and c <= c0 and d >= c1 and (a,b,c,d) != box
                       for a,b,c,d in candidates):
                maximal.append(box)
        for r0, r1, c0, c1 in maximal:
            for r in range(r0, r1 + 1):
                for c in range(c0, c1 + 1):
                    out[r][c] = color
    return out


